"""Root adjudication of scan 021, including all disputed textual and drawn loci."""
from common import *
R=load_page(21);texts={r:(W/f'readers/021/{r}/reading.tex').read_text() for r in 'ABC'}
text=texts['A']
text=text.replace(r"\unsure{is'nt|isn't} -- \illegible{3}",r"\unsure{is'nt|isn't} \unsure{--} \illegible{3}")
text=text.replace("we have only to..''",r"we have only to\unsure{..-|...|..}''")
text=text.replace(r'\deleted{\unsure{(}not -- neither}',r'\deleted{not -- neither}')
text=text.replace("p.102 line -1, ``commute",r"p.102 line -1, \unsure{`|``}commute")
oldraised=r'K\makebox[0pt][l]{\raisebox{1.1ex}{\deleted{\unsure{h}}}}an'
raised=r'K\raisebox{1.1ex}[0pt][0pt]{\makebox[0pt][l]{\deleted{\unsure{h}}}}an'
assert oldraised in text;text=text.replace(oldraised,raised)
wave=r'\draw (0.625,2.2) .. controls (.633,2.65) and (.638,2.45) .. (.643,2.42) .. controls (.649,2.32) and (.653,2.65) .. (.658,2.55);'
wavefinal=wave+'\n'+r'\draw (.644,2.45) -- (.645,2.95);'
assert r'\draw (0,.4)' in text;text=text.replace(r'\draw (0,.4)',wavefinal+'\n'+r'\draw (0,.4)',1)
viewed=[f'crops/021/{x}' for x in ['01_left_rule.jpg','02_right_rule.jpg','03_far_left_trace.jpg','04_isolated_wave.jpg']]
viewed += ['readers/021/C/crops/02_top_right.jpg','readers/021/C/crops/20_p88_reference.jpg','readers/021/B/crops/04_p87_ellipsis.jpg','readers/021/C/crops/03_article.jpg','readers/021/C/crops/04_line8_opener.jpg','readers/021/A/crops/06_cancelled_page_indicator.jpg','readers/021/C/crops/05_occurrences.jpg','readers/021/C/crops/06_not_neither.jpg','readers/021/C/crops/09_english_stop.jpg','readers/021/A/crops/12_cancelled_p.jpg','readers/021/B/crops/13_p99_cancelled_ha.jpg','readers/021/B/crops/14_p102_quotes.jpg','readers/021/B/crops/16_p107_Kan_Khan.jpg','readers/021/C/crops/17_p115_punctuation.jpg']
decisions=[]
def add(id,place,c,final,abc,evidence,crops,confidence='high',kind='other',diff=True):
 decisions.append(dict(id=id,place=place,c=c,h=None,final=final,readers=dict(zip('ABC',abc)),evidence=evidence,crops=crops if isinstance(crops,list) else [crops],confidence=confidence,kind=kind,diff_c=diff,diff_h=False,marked_in_H=False))
add('021-top-dash','Clipped opening, after second contraction','--',r'\unsure{--}',['--',r'\unsure{--}',r'\unsure{--}'],'Only pale horizontal remnants survive in the erased band. Root adopts B/C’s explicit uncertainty: a dash cannot be securely distinguished from a surviving foot of erased writing. No lost word is reconstructed.','readers/021/C/crops/02_top_right.jpg','low')
add('021-p87-low-marks','p.87, after to in second quotation',"to..''",r"to\unsure{..-|...|..}''",["to..''",r"to..\unsure{-|.}''","to..''"],'Root sees two close dark clusters and a separate low horizontal wavy stroke before the raised closer. B counts two points plus a further stroke; A/C treat the low group as two marks, one elongated. The full punctuation span is left doubtful: two points plus a dash-like stroke is favoured, with three points or two marks retained as alternatives. No visible stroke is simply discarded.','readers/021/B/crops/04_p87_ellipsis.jpg','low')
add('021-p88-period-retained','p.88 reference, point after p','p.88','p.88',['p.88','p.88',r'p\unsure{.}88'],'Root sees a separate rounded pale disc at the baseline in the gap after p. Its position and bounded shape support C’s period despite its weaker impression. A/B’s unchanged reading is retained against reader C’s proposed new doubt.','readers/021/C/crops/20_p88_reference.jpg','medium',diff=False)
add('021-live-a','p.88, live article before bit',r'\deleted{\unsure{a|a l}}\unsure{a}',r'\deleted{\unsure{a|a l}}a',[r'\deleted{\unsure{a|a l}}a']*3,'Root confirms the separate rightmost closed oval and a-shaped exit before bit. All readers resolve this live a while keeping the buried earlier cluster doubtful.','readers/021/C/crops/03_article.jpg')
add('021-is-opener','p.89 line 8, extra opening mark before is',r'\unsure{``}is','``is',['``is',r'\unsure{``}is',r'\unsure{``|`}is'],'Root sees two downward legs separated at their lower ends, though joined across the top. This supports A’s double opening quotation. The unmatched extra opener is retained without supplying a closer after is.','readers/021/C/crops/04_line8_opener.jpg','medium')
add('021-deleted-p-dot','p.89 line -15, cancelled reference',r'\deleted{\unsure{p.}}',r'\deleted{p.}',[r'\deleted{p.}']*3,'Root sees a long descender, surviving right upper bowl and separate low point beneath the crossing strokes. All three resolve the cancelled p. from these surviving features.','readers/021/A/crops/06_cancelled_page_indicator.jpg')
add('021-occurences','p.90 marginal count, spelling',r'\unsure{occurences|occurrences}','occurences',['occurences',r'\unsure{occurences|occurrences}','occurences'],'The root crop shows the joined u turns followed by one r shoulder before the e loop. A/C’s one-r reading is adopted against B’s retained alternative; the spelling occurences is not modernized.','readers/021/C/crops/05_occurrences.jpg','medium')
add('021-cancellation-start','p.90, cancelled not -- neither',r'\deleted{\unsure{(}not -- neither}',r'\deleted{not -- neither}',[r'\deleted{\unsure{(}not -- neither}',r'\deleted{not -- neither}',r'\deleted{not -- neither}'],'Root follows the left upright directly into the long rising zigzag cancellation stroke. There is no separate curved parenthesis. B/C’s removal of the conjectural parenthesis is adopted; the words and their deletion remain.','readers/021/C/crops/06_not_neither.jpg')
add('021-English-period','p.91, after English',r'English\unsure{.}','English.',['English.']*3,'Root confirms a detached low black point with a white gap after the h terminal, before the separately crossed only. All three resolve the period.','readers/021/C/crops/09_english_stop.jpg')
add('021-deleted-p','p.91 line -16, cancelled reference',r'\deleted{\unsure{p}}',r'\deleted{p}',[r'\deleted{p}',r'\deleted{p}',r'\deleted{\unsure{p}}'],'Root sees a long descender and a small surviving right-side bowl through the cancellation. These support A/B’s p, with medium confidence because its upper interior is crowded. No following point is supplied.','readers/021/A/crops/12_cancelled_p.jpg','medium')
add('021-deleted-ha','p.99, between X and Y',r'\deleted{\unsure{ha}}',r'\deleted{ha}',[r'\deleted{ha}']*3,'Root sees the looped ascender and low shoulder of h, then the closed a bowl and exit beneath the crossing stroke. The two letters are recovered from their own contours, not from the later live have.','readers/021/B/crops/13_p99_cancelled_ha.jpg')
add('021-p102-opener','p.102, opening mark before commute','``commute',r'\unsure{`|``}commute',['``commute',r'\unsure{`|``}commute',r'\unsure{`|``}commute'],'Root sees one tall compact upright with a left thickening and lower right hook. A single stroke is favoured, but fused doubles cannot be excluded. B/C’s new opening doubt is adopted; the closing pair and with underline remain unchanged.','readers/021/B/crops/14_p102_quotes.jpg','low')
add('021-raised-cancellation','p.107, cancelled cluster over a of Kan',r'K\deleted{\unsure{h}}an',raised,[oldraised,r'K\textsuperscript{\deleted{\unsure{h}}}an',raised],'All readers and the root crop place the black crossed cluster above a, clear of the live baseline. Its interior still does not securely establish h. A zero-width raised placement preserves the location without adding an insertion caret or advancing the following a.','readers/021/B/crops/16_p107_Kan_Khan.jpg',kind='insertion or placement')
add('021-final-colon-retained','p.115, punctuation after page number',r'p.115\unsure{:}',r'p.115\unsure{:}',[r'p.115\unsure{:}',r'p.115\unsure{:}','p.115:'],'Root sees a lower point and an upper oblique curved stroke. Their diagonal offset and the elongated upper mark leave the punctuation’s identity uncertain. A/B’s retained colon doubt is adopted against C’s resolution; both visible marks remain represented by the doubtful colon.','readers/021/C/crops/17_p115_punctuation.jpg','low',diff=False)
Achanges={x['id']:x for x in R['A']['changes']};Cchanges={x['id']:x for x in R['C']['changes']}
Bleft=next(l for l in texts['B'].splitlines() if r'xshift=-.35cm' in l);Bright=next(l for l in texts['B'].splitlines() if r'xshift=.98\linewidth' in l)
for id,aid,cid,bline,crop in [('021-left-rule','left-side-rule','left-vertical-rule',Bleft,'01_left_rule.jpg'),('021-right-rule','right-side-rule','right-vertical-rule',Bright,'02_right_rule.jpg')]:
 x=Achanges[aid];add(id,x['place'],'',x['reading'],[x['reading'],bline,Cchanges[cid]['reading']],'All three readers report the line. Root’s full-length narrow crop, rotated only for inspection, confirms a thin continuous, slightly irregular black rule running across both text sections. It is rendered as an overlay; no editorial function is assigned.','crops/021/'+crop,kind='drawing or diagram')
x=Achanges['far-left-partial-rule'];add('021-far-left-trace',x['place'],'',x['reading'],[x['reading'],'',''],'Root confirms a separate faint near-vertical trace in the left margin over the upper-list region. A’s grey line is adopted; B/C omitted it. Its origin and exact endpoints are not established, so the drawing approximates the visible extent without asserting that it is a deliberate editorial rule.','crops/021/03_far_left_trace.jpg','medium','drawing or diagram')
add('021-isolated-wave','Above divider, left of Sent note','',wavefinal,['',wave,''],'Root confirms an isolated short wavy stroke above and separate from the long horizontal divider, with a small upward twig near its centre. B’s omitted-ink finding is adopted, and the main drawing also includes that visible twig. No word or symbolic meaning is assigned.','crops/021/04_isolated_wave.jpg',kind='drawing or diagram')
cd=doubt_decisions(R['A'],21,'A')
cd[12].update(reading=r'\deleted{not -- neither}',resolved=True,decision='Conjectural parenthesis removed: the upright is part of the deletion zigzag.',evidence='Root inspected readers/021/C/crops/06_not_neither.jpg; the upright runs directly into the rising cancellation stroke, with no independent parenthesis curve.')
cd[9]['confidence']='medium';cd[16]['confidence']='medium'
doubts=[copy.deepcopy(d) for i,d in enumerate(R['A']['remaining_doubts']) if i!=8]
doubts.extend([
 dict(place='Clipped first line, after second contraction',reading=r'\unsure{--}',alternatives='dash; surviving erased-word stroke',confidence='low',reason='Only pale horizontal remnants survive.'),
 dict(place='p.87, low punctuation before closing quote',reading=r'\unsure{..-|...|..}',alternatives='two points and dash-like stroke; three points; two marks with the second elongated',confidence='low',reason='Two close small dark clusters and a separate low wavy stroke survive; the grouping and punctuation values remain ambiguous.'),
 dict(place='p.102, opening quotation before commute',reading=r'\unsure{`|``}',alternatives='single opening quotation; fused double opening quotation',confidence='low',reason='A compact upright with a spur and hook does not securely separate the stroke count.')])
inv={x['element']:copy.deepcopy(x) for x in R['A']['inventory']}
