inv['33'].update(kind='drawing',first_words_or_objects='Upper group crossed by two oblique strokes; exact function not assigned')
inv['56']['kind']='margin note'
order=['37','38','01','39','02','03','33','34','04','05','06','07','08','09','10','35']+[f'{i:02}' for i in range(11,33)]
