inventory.append(inv['36']);inventory.extend(inv[f'{i:02}'] for i in range(40,57))
for i,x in enumerate(inventory,1):x.setdefault('reader_element','A'+x['element']);x['element']=f'{i:02}'
assert len(inventory)==57
notes=R['A']['notes']+['The two oblique strokes are reproduced as visible crossings without deciding whether every word in the upper block was cancelled. The side rules, faint far-left trace and isolated wavy stroke are likewise drawn without an assigned editorial meaning. The faint trace’s origin and exact endpoints are uncertain; its visible geometry is approximated.', 'Root retained uncertainty for the erased top dash, p.87 punctuation group, p.102 opener, buried old letters and final colon. The p.88 point remains a period because a bounded pale disc occupies the normal baseline position. No punctuation or missing parenthesis was supplied merely to regularize the prose.']
