for x in notation:
 if x['sign']=='p., line, -':x['evidence']='Short strokes introduce negative line references; p109 has no stop, while p.88 has a distinct pale baseline point retained after root crop inspection.'
 if x['sign']=='Quotation strokes':x['reading']=r'`` before is; \unsure{`|``} before commute at p.102; `` before developing';x['evidence']='Root crop 04 at p.89 shows two lower legs; p.102 remains a fused-stroke doubt; all readers confirm p.105.'
 if x['sign']=='Two terminal low marks':x.update(sign='Low punctuation group',reading=r"to\unsure{..-|...|..}''",evidence='Root inspected reader B crop 04: two close dark clusters and a separate low wavy stroke; grouping and punctuation value remain doubtful.')
 if x['sign']=='Rule/cancellation geometry':x['reading']='Two long vertical rules; faint far-left partial trace; two oblique crossings; horizontal separator; isolated wavy stroke; curved marginal rule';x['evidence']='The root inspected four new drawing crops and the marginal-note crop; all visible marks are represented in TikZ without assigning editorial intent.'
write_record(21,'A','brief_v06.md',text,decisions,cd,doubts,notes,'All three full readings and all proposed differences were compared. Root inspected fourteen retained reader crops and made four new narrow drawing crops because no reader had cropped those whole marks. The final inventory has 57 rows, including all local deletion/insertion/underline elements and the line drawings; full-page rules are listed first, followed by text order and nested elements. No clipped words were restored from recurring text. H is descriptive only. The table-context input omission was corrected equally for all readers during their crop stage. Reader A attempted a compilation contrary to the source prompt; it failed at the missing-format stage. That attempt and its diagnostic remain documented; root performed static checks only and no compilation completed.',viewed=viewed,inventory=inventory,notation=notation)
